159	export function fmtBytes(b: number): string {
160	  if (!b || b <= 0) return "0 B";
161	  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
162	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
163	  return `${(b / 1024 ** i).toFixed(1)} ${units[i]}`;
164	}
