1	/* Dependency-free SVG charts, safe to render in server components. */
2	
3	function pathFrom(points: [number, number][], smooth = true): string {
4	  if (points.length === 0) return "";
5	  if (!smooth || points.length < 3) {
6	    return points.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
7	  }
8	  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
9	  for (let i = 1; i < points.length; i++) {
10	    const [x0, y0] = points[i - 1];
11	    const [x1, y1] = points[i];
12	    const cx = (x0 + x1) / 2;
13	    d += ` C${cx.toFixed(2)},${y0.toFixed(2)} ${cx.toFixed(2)},${y1.toFixed(2)} ${x1.toFixed(2)},${y1.toFixed(2)}`;
14	  }
15	  return d;
16	}
17	
18	function scale(data: number[], w: number, h: number, pad = 2, max?: number): [number, number][] {
19	  const mx = max ?? Math.max(...data, 1e-9);
20	  const mn = 0;
21	  const n = Math.max(data.length - 1, 1);
22	  return data.map((v, i) => [
23	    (i / n) * (w - pad * 2) + pad,
24	    h - pad - ((v - mn) / (mx - mn || 1)) * (h - pad * 2),
25	  ]);
26	}
27	
28	export function Sparkline({
29	  data,
30	  width = 120,
31	  height = 36,
32	  stroke = "#8a70fb",
33	  id,
34	}: {
35	  data: number[];
36	  width?: number;
37	  height?: number;
38	  stroke?: string;
39	  id: string;
40	}) {
41	  if (data.length === 0) return null;
42	  const pts = scale(data, width, height);
43	  const line = pathFrom(pts);
44	  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
45	  return (
46	    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
47	      <defs>
48	        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
49	          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
50	          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
51	        </linearGradient>
52	      </defs>
53	      <path d={area} fill={`url(#sg-${id})`} />
54	      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
55	    </svg>
56	  );
57	}
58	
59	export function AreaChart({
60	  series,
61	  width = 720,
62	  height = 220,
63	  id,
64	  yLabel,
65	  xLabels = [],
66	  maxY,
67	}: {
68	  series: { name: string; data: number[]; color: string }[];
69	  width?: number;
70	  height?: number;
71	  id: string;
72	  yLabel?: (v: number) => string;
73	  xLabels?: string[];
74	  maxY?: number;
75	}) {
76	  const all = series.flatMap((s) => s.data);
77	  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
78	  const max = maxY ?? Math.max(...all, 1e-9);
79	  const padL = 46;
80	  const padB = 22;
81	  const cw = width - padL - 8;
82	  const ch = height - padB - 8;
83	  const gridLines = 4;
84	
85	  return (
86	    <div className="w-full overflow-x-auto">
87	      <svg
88	        width="100%"
89	        viewBox={`0 0 ${width} ${height}`}
90	        preserveAspectRatio="none"
91	        className="min-w-[480px]"
92	        style={{ height }}
93	      >
94	        <defs>
95	          {series.map((s, si) => (
96	            <linearGradient key={si} id={`ag-${id}-${si}`} x1="0" y1="0" x2="0" y2="1">
97	              <stop offset="0%" stopColor={s.color} stopOpacity="0.30" />
98	              <stop offset="100%" stopColor={s.color} stopOpacity="0" />
99	            </linearGradient>
100	          ))}
101	        </defs>
102	        {Array.from({ length: gridLines + 1 }, (_, i) => {
103	          const y = 8 + (ch / gridLines) * i;
104	          const v = max * (1 - i / gridLines);
105	          return (
106	            <g key={i}>
107	              <line x1={padL} x2={width - 8} y1={y} y2={y} stroke="rgba(255,255,255,0.05)" />
108	              <text x={padL - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill="#64748b">
109	                {yLabel ? yLabel(v) : v.toFixed(0)}
110	              </text>
111	            </g>
112	          );
113	        })}
114	        {xLabels.map((l, i) => (
115	          <text
116	            key={i}
117	            x={padL + (cw / Math.max(xLabels.length - 1, 1)) * i}
118	            y={height - 6}
119	            textAnchor="middle"
120	            fontSize="10"
121	            fill="#64748b"
122	          >
123	            {l}
124	          </text>
125	        ))}
126	        {series.map((s, si) => {
127	          const pts: [number, number][] = s.data.map((v, i) => [
128	            padL + (i / Math.max(s.data.length - 1, 1)) * cw,
129	            8 + ch - (v / max) * ch,
130	          ]);
131	          const line = pathFrom(pts);
132	          const area = `${line} L${(padL + cw).toFixed(2)},${8 + ch} L${padL},${8 + ch} Z`;
133	          return (
134	            <g key={si}>
135	              <path d={area} fill={`url(#ag-${id}-${si})`} />
136	              <path d={line} fill="none" stroke={s.color} strokeWidth="2" strokeLinecap="round" />
137	            </g>
138	          );
139	        })}
140	      </svg>
141	    </div>
142	  );
143	}
