145	export function Donut({
146	  segments,
147	  size = 132,
148	  thickness = 14,
149	  centerLabel,
150	  centerSub,
151	}: {
152	  segments: { value: number; color: string }[];
153	  size?: number;
154	  thickness?: number;
155	  centerLabel?: string;
156	  centerSub?: string;
157	}) {
158	  const total = segments.reduce((n, s) => n + s.value, 0) || 1;
159	  const r = (size - thickness) / 2;
160	  const c = 2 * Math.PI * r;
161	  let offset = 0;
162	  return (
163	    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
164	      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={thickness} />
165	      {segments.map((s, i) => {
166	        const frac = s.value / total;
167	        const el = (
168	          <circle
169	            key={i}
170	            cx={size / 2}
171	            cy={size / 2}
172	            r={r}
173	            fill="none"
174	            stroke={s.color}
175	            strokeWidth={thickness}
176	            strokeLinecap="round"
177	            strokeDasharray={`${(frac * c).toFixed(2)} ${c.toFixed(2)}`}
178	            strokeDashoffset={(-offset * c).toFixed(2)}
179	            transform={`rotate(-90 ${size / 2} ${size / 2})`}
180	          />
181	        );
182	        offset += frac;
183	        return el;
184	      })}
185	      {centerLabel && (
186	        <text x="50%" y={centerSub ? "47%" : "52%"} textAnchor="middle" fontSize="20" fontWeight="700" fill="#f1f5f9">
187	          {centerLabel}
188	        </text>
189	      )}
190	      {centerSub && (
191	        <text x="50%" y="62%" textAnchor="middle" fontSize="10" fill="#64748b">
192	          {centerSub}
193	        </text>
194	      )}
195	    </svg>
196	  );
197	}
