export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

function planFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    "Full root access",
    "Free DDoS protection",
  ];
}

export function PricingGrid({ plans }: { plans: PlanCard[] }) {
  // Highlight the middle plan (by position) as "Most popular".
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;

  if (plans.length === 0) {
    return (
      <div className="card text-center text-slate-400">
        Plans are being provisioned. Please check back shortly.
      </div>
    );
  }

  return (
    <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
      {plans.map((p, i) => {
        const popular = i === popularIdx;
        return (
          <div
            key={p.id}
            className={`relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-200 ${
              popular
                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70"
            }`}
          >
            {popular && (
              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
                Most popular
              </span>
            )}
            <h3 className="text-base font-semibold text-white">{p.name}</h3>
            <div className="mt-3 flex items-end gap-1">
              <span className="text-4xl font-bold tracking-tight">{money(p.priceCents)}</span>
              <span className="mb-1 text-sm text-slate-400">/mo</span>
            </div>
            <ul className="mt-6 flex-1 space-y-3 text-sm">
              {planFeatures(p).map((f) => (
                <li key={f} className="flex items-center gap-2.5 text-slate-300">
                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
                    <IconCheck size={12} />
                  </span>
                  {f}
                </li>
              ))}
            </ul>
            <Link
              href="/register"
              className={`mt-7 w-full ${popular ? "btn-primary" : "btn-secondary"}`}
            >
              Deploy now
            </Link>
          </div>
        );
      })}
    </div>
  );
}

