"use client";

import { useState } from "react";

export type CatalogGroup = { key: string; label: string; items: string[] };

const GRADIENTS = [
  "from-[#e95420] to-[#f4a261]", // ubuntu-ish
  "from-[#a80030] to-[#d33]", // debian-ish
  "from-[#0b7ec9] to-[#22d3ee]",
  "from-[#3b82f6] to-[#8a70fb]",
  "from-[#10b981] to-[#22d3ee]",
  "from-[#8a70fb] to-[#6f47f5]",
];

function Tile({ name, i }: { name: string; i: number }) {
  const initials = name
    .replace(/[^a-zA-Z0-9 ]/g, "")
    .split(" ")
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
  return (
    <div className="group flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3 transition-all duration-200 hover:border-brand-500/30 hover:bg-white/[0.05]">
      <span
        className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br ${
          GRADIENTS[i % GRADIENTS.length]
        } text-[12px] font-bold text-white shadow`}
      >
        {initials}
      </span>
      <span className="truncate text-sm font-medium text-slate-200">{name}</span>
    </div>
  );
}

export function DeployCatalog({ groups }: { groups: CatalogGroup[] }) {
  const [active, setActive] = useState(groups[0]?.key ?? "");
  const current = groups.find((g) => g.key === active) ?? groups[0];

  return (
    <div className="card p-6 sm:p-8">
      <div className="flex flex-wrap gap-2">
        {groups.map((g) => (
          <button
            key={g.key}
            onClick={() => setActive(g.key)}
            className={`rounded-xl px-4 py-2 text-sm font-semibold transition-all ${
              g.key === current?.key
                ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow-lg"
                : "border border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"
            }`}
          >
            {g.label}
            <span className="ml-2 text-xs opacity-70">{g.items.length}</span>
          </button>
        ))}
      </div>

      <div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {current?.items.map((item, i) => (
          <Tile key={item} name={item} i={i} />
        ))}
      </div>
    </div>
  );
}

