export const metadata: Metadata = {
  title: "Pricing — Nxeon",
  description: "Simple, predictable VPS pricing. Full root access, NVMe storage, and DDoS protection on every plan.",
};

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

const FAQ = [
  { q: "Is there a free trial?", a: "You can create an account with no credit card. Free VPS offers appear in your dashboard when available; otherwise you only pay for servers you keep running, billed monthly from your wallet." },
  { q: "Can I upgrade or downgrade later?", a: "Yes. Resize a server's vCPU, RAM, and disk from the dashboard as your needs change — no need to rebuild from scratch." },
  { q: "What's included on every plan?", a: "Full root access over SSH, enterprise NVMe storage, a dedicated IPv4 address, always-on DDoS protection, automatic backups, and one-click OS reinstalls." },
  { q: "How does billing work?", a: "Billing is prepaid from a wallet balance in your account. Top up, and servers auto-renew each month. Cancel anytime and the server stops billing at the end of the period." },
  { q: "Do you offer refunds?", a: "Unused wallet balance and service credits are handled per our Terms of Service and SLA. Reach out via the contact page and we'll help." },
  { q: "Which operating systems can I run?", a: "Ubuntu, Debian, AlmaLinux, Rocky Linux and more, plus control panels and one-click apps that deploy fully configured on first boot." },
];

const COMPARISON = [
  "Full root access",
  "NVMe SSD storage",
  "Dedicated IPv4",
  "DDoS protection",
  "Automatic backups",
  "One-click reinstall",
  "Real-time metrics",
];

export default async function PricingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });

  return (
    <>
      <section className="relative overflow-hidden">
        <div
          className="pointer-events-none absolute inset-x-0 top-0 h-[420px] opacity-70"
          style={{ backgroundImage: "radial-gradient(ellipse 60% 50% at 50% 0%, rgba(59,130,246,0.16), transparent)" }}
