"use client";

import { useState } from "react";
import { IconArrow, IconMail } from "./icons";

const SUPPORT_EMAIL = "support@nxeon.cloud";

export function ContactForm() {
  const [sent, setSent] = useState(false);

  function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    const name = String(data.get("name") ?? "");
    const email = String(data.get("email") ?? "");
    const subject = String(data.get("subject") ?? "Nxeon enquiry");
    const message = String(data.get("message") ?? "");

    const body = `Name: ${name}\nEmail: ${email}\n\n${message}`;
    const href = `mailto:${SUPPORT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    // No backend: open the visitor's mail client pre-filled.
    window.location.href = href;
    setSent(true);
  }

  return (
    <form onSubmit={onSubmit} className="card space-y-4">
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label" htmlFor="name">Name</label>
          <input id="name" name="name" className="input" required autoComplete="name" />
        </div>
        <div>
          <label className="label" htmlFor="email">Email</label>
          <input id="email" name="email" type="email" className="input" required autoComplete="email" />
        </div>
      </div>
      <div>
        <label className="label" htmlFor="subject">Subject</label>
        <input id="subject" name="subject" className="input" placeholder="How can we help?" required />
      </div>
      <div>
        <label className="label" htmlFor="message">Message</label>
        <textarea id="message" name="message" className="input min-h-[140px] resize-y" required />
      </div>

      <button className="btn-primary w-full py-3 text-base" type="submit">
        <IconMail size={16} />
        Send message
        <IconArrow size={16} />
      </button>

      {sent && (
        <p className="text-center text-sm text-emerald-400">
          Opening your email client… If nothing happened, email us directly at{" "}
          <a href={`mailto:${SUPPORT_EMAIL}`} className="underline">{SUPPORT_EMAIL}</a>.
        </p>
      )}
      <p className="text-center text-xs text-slate-500">
        This form has no backend — it opens your mail client pre-filled. Support address is a
        placeholder; swap in your real inbox before launch.
      </p>
    </form>
  );
}

