import Link from "next/link";
import { NxMark } from "./Logo";
import { IconCheck } from "./icons";

/**
 * Two-pane auth shell: a gradient value-prop panel on wide screens and a
 * glass card holding the form. Purely presentational — the form is passed in.
 */
export function AuthShell({
  heading,
  sub,
  bullets,
  children,
}: {
  heading: string;
  sub: string;
  bullets: string[];
  children: React.ReactNode;
}) {
  return (
    <main className="grid min-h-screen lg:grid-cols-2">
      {/* Value-prop panel */}
      <aside className="relative hidden overflow-hidden border-r border-white/[0.06] lg:flex lg:flex-col lg:justify-between lg:p-12">
        <div
          className="pointer-events-none absolute inset-0 opacity-90"
          style={{
            backgroundImage:
              "radial-gradient(ellipse 70% 60% at 20% 10%, rgba(59,130,246,0.18), transparent), radial-gradient(ellipse 60% 60% at 90% 90%, rgba(138,112,251,0.20), transparent)",
          }}
        />
        <div className="relative">
          <Link href="/" className="flex items-center gap-2.5">
            <NxMark id="auth" size={30} />
            <span className="text-[17px] font-bold tracking-[0.18em]">NXEON</span>
          </Link>
        </div>

        <div className="relative">
          <h2 className="max-w-md text-4xl font-extrabold leading-tight tracking-tight">
            Premium cloud, <span className="grad-text">provisioned in seconds</span>
          </h2>
          <ul className="mt-8 space-y-4">
            {bullets.map((b) => (
              <li key={b} className="flex items-center gap-3 text-slate-300">
                <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
                  <IconCheck size={14} />
                </span>
                {b}
              </li>
            ))}
          </ul>
        </div>

        <p className="relative text-sm text-slate-500">
          © {new Date().getFullYear()} Nxeon. NVMe VPS hosting, built for scale.
        </p>
      </aside>

      {/* Form pane */}
      <div className="relative flex items-center justify-center p-6">
        <div
          className="pointer-events-none absolute inset-0 opacity-70 lg:hidden"
          style={{ backgroundImage: "radial-gradient(ellipse 80% 50% at 50% 0%, rgba(111,71,245,0.16), transparent)" }}
        />
        <div className="relative w-full max-w-sm">
          <Link href="/" className="mb-8 flex items-center justify-center gap-2.5 lg:hidden">
            <NxMark id="auth-m" size={30} />
            <span className="text-[17px] font-bold tracking-[0.18em]">NXEON</span>
          </Link>

          <div className="card glow-brand">
            <h1 className="text-xl font-semibold">{heading}</h1>
            <p className="mt-1 mb-6 text-sm text-slate-400">{sub}</p>
            {children}
          </div>

          <p className="mt-6 text-center text-xs text-slate-500">
            By continuing you agree to our{" "}
            <Link href="/legal/terms" className="text-slate-400 hover:text-white hover:underline">
              Terms
            </Link>{" "}
            and{" "}
            <Link href="/legal/privacy" className="text-slate-400 hover:text-white hover:underline">
              Privacy Policy
            </Link>
            .
          </p>
        </div>
      </div>
    </main>
  );
}

